export const EXPOSURE_NOTE = "露出は被害ではない。damage_state・debris_present・official_closure・通行可否を導出しない。";

/** Fixed guard/disclaimer sentences. Verbatim only; the scanner allowlist is built from these. */
export const ADMIN_CHECKLIST_GUARD_TEXTS = Object.freeze([
  "この表は行政による検証結果ではありません。通行可否・安全性・アクセシビリティの判定を含みません。",
  "露出は被害ではない。",
  "UNKNOWNは通行不可でも可でもない。",
  "priority_rank は並び順の機械規則であり、危険度・重要度ではありません。",
  EXPOSURE_NOTE,
]);

function schemaProseStrings(node, out = []) {
  if (Array.isArray(node)) { for (const value of node) schemaProseStrings(value, out); return out; }
  if (node && typeof node === "object") {
    for (const [key, value] of Object.entries(node)) {
      if ((key === "title" || key === "description") && typeof value === "string") out.push(value);
      else schemaProseStrings(value, out);
    }
  }
  return out;
}

/**
 * Verbatim strings a forbidden-expression scan may subtract before asserting zero hits.
 * Only exact fixed sentences belong here: no wildcards, no regular expressions.
 */
export const ADMIN_CHECKLIST_ALLOWED_TEXTS = Object.freeze([
  ...ADMIN_CHECKLIST_GUARD_TEXTS,
  ...schemaProseStrings(ADMIN_CHECKLIST_SCHEMA),
]);

/** Words that must never appear outside the allowlisted fixed sentences. */
export const ADMIN_CHECKLIST_FORBIDDEN_WORDS = Object.freeze([
  "安全な避難ルート", "安全", "危険", "通行可", "通行不可", "再現", "救える",
]);

export function scanForbiddenExpressions(text, allowed = ADMIN_CHECKLIST_ALLOWED_TEXTS) {
  let residue = String(text);
  for (const sentence of [...allowed].sort((left, right) => right.length - left.length)) {
    residue = residue.split(sentence).join(" ");
  }
  return ADMIN_CHECKLIST_FORBIDDEN_WORDS.filter((word) => residue.includes(word));
}

/** Validate the public exposure boundary; never fill absent evidence with zero. */
export function validateExposureFlags(value) {
  if (value?.status === "PUBLIC_PAYLOAD_EXCLUDED") {
    if (value.records !== null || value.a31b_overlap_counts !== null || typeof value.reason !== "string" || !value.reason.trim()) throw new Error("excluded exposure must remain null with a reason");
  } else if (value?.status !== "SOURCE_RECORDS" || !Number.isInteger(value.records) || value.records < 0 || !value.a31b_overlap_counts || value.reason !== null) {
    throw new Error("invalid exposure source records");
  }
}

/** Header lines printed above every checklist print view. Data comes from the checklist header. */
export function adminChecklistPrintHeaderLines(checklist) {
  const sources = Object.entries(checklist?.generated_from ?? {}).map(([path, sha256]) => `${path} ${sha256}`);
  return [
    `AblePath 行政確認ワークフロー（${checklist?.city_id ?? "null"} / generated_at ${checklist?.generated_at ?? "null"}）`,
    ...ADMIN_CHECKLIST_GUARD_TEXTS.slice(0, 4),
    `出典: ${sources.join(" / ")}`,
    `M6: ${checklist?.m6_status ?? "null"} / M7: ${checklist?.m7_status ?? "null"}`,
  ];
}

export const ADMIN_CHECKLIST_CSV_COLUMNS = Object.freeze([
  "item_id", "city_id", "subarea_id", "object_type", "object_id", "attribute", "status",
  "source_id", "source_revision", "source_sha256", "unknown_reason", "verification_method",
  "verification_target.label", "verification_target.receipt_path", "verification_target.dataset_ids",
  "verification_target.note", "priority_rank", "priority_rule", "exposure_flags",
  "human_fields.assignee", "human_fields.due", "human_fields.result", "human_fields.note",
  "export_ready", "internal_use_only",
]);

function cell(value) {
  if (value === null || value === undefined) return "";
  const text = typeof value === "string" ? value : JSON.stringify(value);
  return /[",\n\r]/.test(text) ? `"${text.split('"').join('""')}"` : text;
}

function column(item, name) {
  if (name === "exposure_flags") return item.exposure_flags === null ? "" : JSON.stringify(item.exposure_flags);
  if (name === "verification_target.dataset_ids") return JSON.stringify(item.verification_target?.dataset_ids ?? []);
  const [head, tail] = name.split(".");
  const value = tail === undefined ? item[head] : item[head]?.[tail];
  return typeof value === "boolean" || typeof value === "number" ? String(value) : value ?? null;
}

/** RFC4180 serializer. LF line endings, no BOM. Pure. */
export function toChecklistCsv(items) {
  const rows = [ADMIN_CHECKLIST_CSV_COLUMNS.join(",")];
  for (const item of items) rows.push(ADMIN_CHECKLIST_CSV_COLUMNS.map((name) => cell(column(item, name))).join(","));
  return `${rows.join("\n")}\n`;
}

/**
 * Code-point comparison. localeCompare is not used anywhere in the generated
 * ordering: its result depends on the host ICU data, which would make the
 * generated bytes machine-dependent.
 */
export function compareCodePoints(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

/** Default machine ordering: priority_rank, then object_type, object_id, attribute (all by code point, stable). */
export function sortChecklistItems(items) {
  return [...items].sort((left, right) =>
    left.priority_rank - right.priority_rank
    || compareCodePoints(left.object_type, right.object_type)
    || compareCodePoints(left.object_id, right.object_id)
    || compareCodePoints(left.attribute, right.attribute)
    || compareCodePoints(left.item_id, right.item_id));
}
